export const getGetArticleContentUrl = (id: string,
    params?: GetArticleContentParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/tripwire/records/${id}/content?${stringifiedParams}` : `/api/tripwire/records/${id}/content`
}

